const $=id=>document.getElementById(id),num=(n,d=0)=>n.toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d}),money=n=>'₹'+num(n),metric=(label,value,note='')=>`<div class="metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;
const annual=calculate({view:'annual'}),quarterly=calculate();
$('overview-metrics').innerHTML=metric('ANNUAL-MIX BOOKINGS','~'+num(annual.bookings),'12 CRM promotions')+metric('ANNUAL-MIX BLENDED CAC','~'+money(annual.cac),'vs target '+money(PLAN.targetCAC))+metric('ANNUAL GAP VS '+num(PLAN.target),'~'+num(annual.gap),'Travellers still to find')+metric('QUARTERLY-AWARE BOOKINGS','~'+num(quarterly.bookings),'CAC ~'+money(quarterly.cac)+' · 11 CRM promos');
const ads=[{id:'a-safety',title:'Safety',icp:'First-time solo joiner',proof:'Trip-lead role + support process, proposed',dest:'safety',page:'Detail → trip lead / safety',cta:'See the trip lead and process',principle:'Authority through a proposed, verifiable role.'},{id:'b-group',title:'Group quality',icp:'Solo joiner / warm undecided contact',proof:'Group expectations and a hosted day',dest:'group-fit',page:'Detail → group fit',cta:'See group expectations',principle:'Future consented stories are proposed social proof only.'},{id:'c-costs',title:'Hidden costs',icp:'Budget-conscious planner',proof:'Inclusions / exclusions and case price band',dest:'listing',page:'Listing → detail inclusions',cta:'Compare inclusions',principle:'Reciprocity through useful cost clarity.'},{id:'d-cancellation',title:'Cancellation uncertainty',icp:'Planner / undecided waitlist contact',proof:'Plain-language policy labelled SAMPLE',dest:'cancellation',page:'Detail → SAMPLE cancellation',cta:'Read the sample policy',principle:'No invented scarcity. No seats-left claim.'}];
$('ad-grid').innerHTML=ads.map((a,i)=>`<article><a class="ad-visual" href="#${a.dest==='listing'?'pages':a.dest}" data-destination="${a.dest}" aria-label="Ad ${String.fromCharCode(65+i)}: ${a.title}. ${a.cta}"><img src="ads/ad-${a.id}.png" width="1080" height="1080" alt="YatraLoop sponsored creative for ${a.icp}: ${a.title}. ${a.proof}." loading="lazy"></a><div class="ad-meta"><h3>${String.fromCharCode(65+i)} / ${a.title}</h3><span class="tag">ICP FIT</span></div><p class="ad-caption"><b>Who:</b> ${a.icp}. <b>Barrier:</b> ${a.title.toLowerCase()}. <b>Proof:</b> ${a.proof}.<br><b>Opens:</b> ${a.page}. ${a.principle}</p><a class="ad-cta" href="#pages" data-destination="${a.dest}">${a.cta} →</a></article>`).join('');
$('destinations').innerHTML=['Goa','Himachal','Meghalaya','Rajasthan','North East'].map(name=>`<article class="destination"><div class="landscape" aria-hidden="true"></div><h4>${name}</h4><p>Hosted group trip<br><b>₹7,000–₹25,000</b> · overall case band</p><p>Dates, captain and final payable amount confirmed before booking</p><button type="button" data-trip="${name}">Open trip detail →</button></article>`).join('');
let listingTarget='inclusions';
function openPage(dest){const list=dest==='listing';$('listing').hidden=!list;$('detail').hidden=list;$('listing-tab').setAttribute('aria-pressed',String(list));$('detail-tab').setAttribute('aria-pressed',String(!list));requestAnimationFrame(()=>{const target=$(list?'pages':dest==='detail'?'detail':dest);target.scrollIntoView({behavior:'smooth',block:'start'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});}
document.querySelectorAll('[data-destination]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();listingTarget='inclusions';openPage(a.dataset.destination);}));
document.querySelectorAll('[data-trip]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.trip==='Himachal')openPage(listingTarget);else $('destination-message').textContent=`${b.dataset.trip}: Example detail not built — Himachal is the walkthrough destination.`;}));
$('listing-tab').onclick=()=>openPage('listing');$('detail-tab').onclick=()=>openPage('detail');$('book').onclick=()=>$('review').showModal();$('close-review').onclick=()=>$('review').close();
function funnel(values){return values.map((v,i)=>`<div class="funnel-step"><div class="funnel-label"><span>${['Impressions','Clicks','LP visits','Leads','Bookings'][i]}</span><b>${i===0?num(v/1000000,2)+'m':num(v,i===4?2:0)}</b></div><div class="funnel-track"><div class="funnel-bar" style="width:${[100,80,61,42,24][i]}%"></div></div></div>`).join('');}
$('base-funnel').innerHTML=funnel(annual.metaFunnel);
$('mini-capacity').innerHTML=quarterly.quarters.map((v,i)=>`<div class="mini-row"><span>Q${i+1}</span><div class="mini-track"><div class="mini-fill" style="width:${v/PLAN.caps[i]*100}%"></div></div><span>${num(v)} / ${PLAN.caps[i]}</span></div>`).join('');
function render(){const view=$('view').value,aov=Number($('aov').value),q3=Number($('q3').value),testRate=Number($('test-rate').value),r=calculate({view,aov,q3,testRate}),isAnnual=view==='annual';
$('view-label').textContent=isAnnual?'Annual mix / 12 CRM promotions':'Quarterly capacity-aware / '+(9+q3)+' CRM promotions';
$('change-note').textContent=`${isAnnual?'Annual mix always uses 12 CRM promotions; Q3 lever applies only to quarterly view.':'Quarterly base withholds one Q3 promotion (94.08 bookings).'} Scenario trip value ${money(aov)}; test uplift +${num(r.uplift,2)} bookings. All KPIs below use this selected view.`;
$('q3').disabled=isAnnual;
$('dashboard-kpis').innerHTML=metric('EXPECTED BOOKINGS','~'+num(r.bookings),num(r.bookings,2)+' calculated')+metric('BLENDED CAC','~'+money(r.cac),'vs '+money(PLAN.targetCAC)+' target')+metric('STATED PLAN SPEND','₹30 lakh','Includes ₹8 lakh creators')+metric('GROSS BOOKING ROAS',num(r.roas,2)+'×','Implied target '+num(r.targetRoas,2)+'×')+metric('GAP VS '+num(PLAN.target),'~'+num(r.gap),'Selected planning view');
const over=r.quarters.map((v,i)=>v>PLAN.caps[i]?`Q${i+1}: ${num(v,2)} exceeds capacity ${PLAN.caps[i]} by ${num(v-PLAN.caps[i],2)}.`:'').filter(Boolean);
$('capacity-warning').textContent=over.length?'Capacity warning — '+over.join(' ')+' Forecast is uncapped to expose the overflow.':'';
$('live-funnel').innerHTML=funnel(r.metaFunnel);
$('quarter-chart').innerHTML=r.quarters.map((v,i)=>`<div class="chart-row ${v>PLAN.caps[i]?'overflow':''}"><b>Q${i+1}</b><div><div class="bar-cap" style="width:${PLAN.caps[i]/Math.max(...PLAN.caps)*100}%"><div class="bar-expected" style="width:${v/PLAN.caps[i]*100}%"></div></div><div class="chart-values">${num(v,2)} expected / ${PLAN.caps[i]} cap${v>PLAN.caps[i]?' · OVER CAP':''}</div></div></div>`).join('');
$('table-caption').textContent='Channel economics / '+(isAnnual?'annual mix':'quarterly capacity-aware');
$('channels').innerHTML=r.channels.map(c=>`<tr><th scope="row">${c.name}</th><td>${c.spend===null?'Unknown':money(c.spend)}</td><td>${c.bookings===null?'Not attributed':num(c.bookings,2)}</td><td>${c.spend===null?'Unpriced':c.bookings===null?'Not attributed':money(c.spend/c.bookings)}</td><td>${c.spend===null?'Unpriced':c.bookings===null?'Not attributed':num(c.bookings*aov/c.spend,2)+'×'}</td></tr>`).join('');
const currentAnnual=calculate({view:'annual',testRate,aov});$('crm-insight').textContent=num(PLAN.derivedBase.crm.annualBookings/currentAnnual.bookings*100,1)+'% of annual-mix bookings come from CRM.';
$('test-conclusion').textContent=`At the selected test rate, this view reaches ${num(r.bookings,2)} travellers. The ₹3 lakh test alone does not fund 1,250 on the quarterly base view (12% sensitivity: ~1,158).`;
}
$('levers').addEventListener('change',render);$('levers').addEventListener('reset',()=>setTimeout(render,0));
$('rejected').textContent=`Illustration — we do not recommend this path. Rounded gap ${PLAN.rejectedPath.roundedGap} × Meta CAC ${money(PLAN.rejectedPath.constantMetaCAC)} + ₹30 lakh ≈ ₹${num(PLAN.rejectedPath.totalSpend/10000000,3)} crore; blended CAC at 1,800 ≈ ${money(PLAN.rejectedPath.totalSpend/PLAN.target)} (~₹7,800).`;
$('assumptions').innerHTML=PLAN.assumptions.map(([label,text])=>`<p><b>${label}:</b> ${text}</p>`).join('');
$('presenter').onclick=()=>{const active=document.body.classList.toggle('presenting');$('presenter').setAttribute('aria-pressed',String(active));$('presenter').textContent=active?'Exit presenter ↙':'Presenter mode ↗';};
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target.tagName)||$('review').open)return;const index=Number(e.key)-1,ids=['overview','ads','pages','how','dashboard'];const dest=e.key.toLowerCase()==='d'?'dashboard':ids[index];if(dest){e.preventDefault();$(dest).scrollIntoView();$(dest).setAttribute('tabindex','-1');$(dest).focus({preventScroll:true});}});
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}},{rootMargin:'-15% 0px -65% 0px'});document.querySelectorAll('main>section').forEach(s=>observer.observe(s));render();
